const id = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
const formatDate = (value: string) => value.replace('T', ' ').slice(0, 16);
const AVATAR_PLACEHOLDER = `${import.meta.env.BASE_URL}assets/agent-avatar-placeholder.png`;
const DEFAULT_REPLY_LANGUAGE = '英语';
const REPLY_LANGUAGES = ['简体中文', '繁体中文', '英语', '越南语', '泰语', '高棉语', '缅甸语', '老挝语'];
const statusMap = { draft: ['未发布', 'warning'], published: ['已发布', 'success'] } as const;
const AGENT_DETAIL_SECTIONS = [{ key: 'agent', label: '个人资料' }, { key: 'knowledge', label: '知识库' }, { key: 'workflow', label: '工作流' }, { key: 'reception', label: '接待设置' }] as const;
const AGENT_DETAIL_SECTION_TITLES: Record<string, string> = { agent: '个人资料', workflow: '工作流', reception: '接待设置' };
const DEFAULT_RECEPTION_CONFIG: ReceptionConfig = {
  welcomeEnabled: false,
  welcomeMessage: '',
  noMessageFollowUpEnabled: false,
  noMessageFollowUpDelaySeconds: 30,
  noMessageFollowUpMessage: '',
  afterReplyFollowUpEnabled: false,
  afterReplyFollowUpDelaySeconds: 60,
  afterReplyFollowUpMessage: '',
  closingMessageEnabled: false,
  closingMessage: '',
};

function StatusTag({ status, children }: { status?: keyof typeof statusMap; children?: React.ReactNode }) {
  if (status) { const [label, color] = statusMap[status]; return <Tag color={color}>{label}</Tag>; }
  return <Tag>{children}</Tag>;
}

function PageHeader({ title, breadcrumb = [], status, actions, extra }: { title: React.ReactNode; breadcrumb?: string[]; status?: keyof typeof statusMap; actions?: React.ReactNode; extra?: React.ReactNode }) {
  return <div className="page-header"><div className="page-header-left">{breadcrumb.length > 0 && <div className="breadcrumb">{breadcrumb.map((item, index) => <span key={`${item}-${index}`}>{index > 0 ? ' / ' : ''}{item}</span>)}</div>}<div className="page-title-row"><h1 className="page-title">{title}</h1>{status && <StatusTag status={status} />}{extra}</div></div><div className="page-header-actions">{actions}</div></div>;
}

function AgentListPage() {
  const { state, dispatch } = useAppStore();
  const navigate = useNavigate();
  const toast = Message;
  const [deleting, setDeleting] = useState<Agent>();
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState<'all' | Agent['status']>('all');
  const agents = state.agents.filter((agent) => `${agent.name}${agent.description}`.toLowerCase().includes(query.toLowerCase()) && (status === 'all' || agent.status === status));
  const createAgent = () => {
    const newAgent: Agent = { id: id('agent'), name: '', description: '', avatar: AVATAR_PLACEHOLDER, status: 'draft', updatedAt: now(), teamIds: [DEFAULT_TEAM_ID], acceptingChats: false, draft: { prompt: '', language: DEFAULT_REPLY_LANGUAGE, style: '自然', memoryEnabled: true, memoryDays: 7, historyRounds: 10, errorMessage: '抱歉，我暂时无法完成本次回复，请稍后再试或联系人工支持。', transferToHuman: { enabled: true, mode: 'automatic' }, reception: DEFAULT_RECEPTION_CONFIG, flows: [], skillIds: [], knowledgeIds: [], guards: [], variables: [] }, published: null };
    dispatch({ type: 'agent.add', agent: newAgent }); toast.success('AI Agent 草稿已创建'); navigate(`/agents/${newAgent.id}/agent`);
  };
  const copyAgent = (agent: Agent) => { const copied: Agent = { ...JSON.parse(JSON.stringify(agent)), id: id('agent'), name: `${agent.name || '未命名'}_副本`, status: 'draft', published: null, acceptingChats: false, updatedAt: now() }; dispatch({ type: 'agent.add', agent: copied }); };
  const cardMenu = (agent: Agent) => <div onClick={(event: MouseEvent<HTMLDivElement>) => event.stopPropagation()}><Menu className="agent-more-menu" onClickMenuItem={(key) => {
    if (key === 'copy') copyAgent(agent);
    if (key === 'delete') setDeleting(agent);
  }}><Menu.Item key="copy"><IconCopy />复制 AI Agent</Menu.Item><Menu.Item key="delete" className="danger-menu-item"><IconDelete />删除 AI Agent</Menu.Item></Menu></div>;
  return <div className="page-content agent-home"><PageHeader title="AI Agent" actions={<Button type="primary" icon={<IconPlus />} onClick={createAgent}>新建 AI Agent</Button>} /><div className="filter-bar"><div className="filter-actions"><Input.Search allowClear value={query} onChange={setQuery} placeholder="搜索 AI Agent 名称" style={{ width: 244 }} /><Select value={status} onChange={(value: 'all' | Agent['status']) => setStatus(value)} options={[{ label: '全部状态', value: 'all' }, { label: '已发布', value: 'published' }, { label: '未发布', value: 'draft' }]} style={{ width: 132 }} /></div></div>{agents.length ? <div className="agent-grid">{agents.map((agent) => <Card key={agent.id} className="section-card agent-card" role="link" tabIndex={0} onClick={() => navigate(`/agents/${agent.id}/agent`)} onKeyDown={(event: KeyboardEvent<HTMLElement>) => { if (event.currentTarget !== event.target || !['Enter', ' '].includes(event.key)) return; event.preventDefault(); navigate(`/agents/${agent.id}/agent`); }}><div className="agent-card-top"><div className="agent-identity"><div className="agent-avatar"><img src={agent.avatar || AVATAR_PLACEHOLDER} alt="" />{agent.acceptingChats && <span className="agent-online-dot" />}</div><div className="agent-name">{agent.name || '未命名'}</div></div><div className={`agent-status agent-status-${agent.status}`}>{agent.status === 'published' ? '已发布' : '未发布'}</div></div><div className="agent-description">{agent.description || '暂无简介'}</div><div className="agent-card-footer"><span className="agent-card-update">最近更新：{formatDate(agent.updatedAt)}</span><div className="agent-card-actions"><Button type="primary" onClick={(event: MouseEvent<HTMLButtonElement>) => { event.stopPropagation(); navigate(`/agents/${agent.id}/agent`); }}>配置</Button><Dropdown trigger="click" position="br" droplist={cardMenu(agent)}><Button aria-label={`更多${agent.name || '未命名'}操作`} icon={<IconMore />} onClick={(event: MouseEvent<HTMLButtonElement>) => event.stopPropagation()} /></Dropdown></div></div></Card>)}</div> : <Empty description="没有找到匹配的 AI Agent"><Button type="primary" onClick={createAgent}>新建 AI Agent</Button></Empty>}<Modal open={Boolean(deleting)} title="确认删除 AI Agent？" okText="删除" okButtonProps={{ status: 'danger' }} onCancel={() => setDeleting(undefined)} onOk={() => { if (!deleting) return; dispatch({ type: 'agent.delete', id: deleting.id }); toast.success('AI Agent 已删除'); setDeleting(undefined); }}>删除后相关渠道也会停止接待。</Modal></div>;
}

function AgentBasics({ agent }: { agent: Agent }) {
  const [form] = Form.useForm();
  const { dispatch } = useAppStore();
  const saveTimer = useRef<number | undefined>(undefined);
  const avatarInputId = `agent-avatar-upload-${agent.id}`;

  useEffect(() => () => window.clearTimeout(saveTimer.current), []);

  const save = (values: Record<string, any>) => {
    window.clearTimeout(saveTimer.current);
    saveTimer.current = window.setTimeout(() => {
      const { prompt, language, style } = values;
      dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, prompt: prompt ?? '', language: language ?? agent.draft.language, style: style ?? agent.draft.style } });
    }, 400);
  };
  const updateAvatar = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => dispatch({ type: 'agent.update', id: agent.id, patch: { avatar: String(reader.result) } });
    reader.readAsDataURL(file);
    event.currentTarget.value = '';
  };

  return <div className="agent-config-form"><Form form={form} layout="vertical" initialValues={{ prompt: agent.draft.prompt, language: agent.draft.language, style: agent.draft.style }} onValuesChange={(_changed: Record<string, any>, values: Record<string, any>) => save(values)}>
    <section className="detail-section"><div className="detail-section-head"><h2>人设</h2></div><div className="detail-section-body"><div className="profile-basic-grid"><div className="profile-name-field"><div className="profile-avatar-control"><Tooltip title="点击上传头像"><Button type="text" className="profile-avatar-upload" aria-label="上传 AI Agent 头像" onClick={() => document.getElementById(avatarInputId)?.click()}><img src={agent.avatar || AVATAR_PLACEHOLDER} alt="" /></Button></Tooltip><span className="profile-avatar-edit" aria-hidden="true"><IconEdit /></span></div><input id={avatarInputId} type="file" accept="image/*" hidden onChange={updateAvatar} /><Form.Item label="名称" required><Input value={agent.name} maxLength={50} placeholder="请输入 AI Agent 名称" onChange={(name) => dispatch({ type: 'agent.update', id: agent.id, patch: { name } })} /></Form.Item></div><Form.Item label="简介"><Input value={agent.description} maxLength={200} placeholder="说明 AI Agent 用途、能力范围或服务场景" onChange={(description) => dispatch({ type: 'agent.update', id: agent.id, patch: { description } })} /></Form.Item></div><Form.Item className="profile-prompt" name="prompt" label="系统提示词"><Input.TextArea autoSize={{ minRows: 1, maxRows: 8 }} showCount maxLength={10000} placeholder="请输入系统提示词" /></Form.Item><Row gutter={16}><Col xs={24} md={12}><Form.Item name="language" label="回复语言"><Select options={REPLY_LANGUAGES.map((value) => ({ value, label: value === DEFAULT_REPLY_LANGUAGE ? <span className="language-default-option">{value}<Tag size="small" color="arcoblue">默认</Tag></span> : value }))} /></Form.Item></Col><Col xs={24} md={12}><Form.Item name="style" label="回复风格"><Select options={['自然', '正式', '简洁', '耐心', '热情'].map((value) => ({ label: value, value }))} /></Form.Item></Col></Row></div></section>
  </Form></div>;
}

function ReceptionSection({ agent }: { agent: Agent }) {
  const { dispatch } = useAppStore();
  const reception: ReceptionConfig = { ...DEFAULT_RECEPTION_CONFIG, ...agent.draft.reception };
  const save = (patch: Partial<ReceptionConfig>) => dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, reception: { ...reception, ...patch } } });
  const updateDelay = (key: 'noMessageFollowUpDelaySeconds' | 'afterReplyFollowUpDelaySeconds', value?: number) => save({ [key]: Math.max(1, Math.floor(Number(value) || 1)) } as Partial<ReceptionConfig>);
  const followUpScenario = (
    title: string,
    enabledKey: 'noMessageFollowUpEnabled' | 'afterReplyFollowUpEnabled',
    delayKey: 'noMessageFollowUpDelaySeconds' | 'afterReplyFollowUpDelaySeconds',
    messageKey: 'noMessageFollowUpMessage' | 'afterReplyFollowUpMessage',
    placeholder: string,
  ) => <div className="reception-scenario">
    <div className="reception-scenario-head"><span>{title}</span><Switch checked={Boolean(reception[enabledKey])} onChange={(checked) => save({ [enabledKey]: checked } as Partial<ReceptionConfig>)} aria-label={`${title}开关`} /></div>
    {reception[enabledKey] && <div className="reception-scenario-body">
      <div className="reception-delay-row"><span>等待时间</span><InputNumber min={1} precision={0} value={reception[delayKey]} onChange={(value) => updateDelay(delayKey, value as number)} /><span>秒</span></div>
      <Input.TextArea value={String(reception[messageKey] || '')} maxLength={500} showCount autoSize={{ minRows: 3, maxRows: 8 }} placeholder={placeholder} onChange={(value: string) => save({ [messageKey]: value } as Partial<ReceptionConfig>)} />
    </div>}
  </div>;

  return <div className="reception-settings">
    <section className="detail-section reception-card"><div className="detail-section-head"><h2>欢迎语</h2><Switch checked={reception.welcomeEnabled} onChange={(checked) => save({ welcomeEnabled: checked })} aria-label="欢迎语开关" /></div>{reception.welcomeEnabled && <div className="detail-section-body"><Input.TextArea value={reception.welcomeMessage} maxLength={500} showCount autoSize={{ minRows: 3, maxRows: 8 }} placeholder="请输入欢迎语" onChange={(welcomeMessage: string) => save({ welcomeMessage })} /></div>}</section>
    <section className="detail-section reception-card"><div className="detail-section-head"><h2>跟进语</h2></div><div className="detail-section-body reception-follow-up-list">
      {followUpScenario('客户进入聊天后未发送消息', 'noMessageFollowUpEnabled', 'noMessageFollowUpDelaySeconds', 'noMessageFollowUpMessage', '请输入客户进入聊天后未发送消息时的跟进语')}
      {followUpScenario('AI Agents 回复后客户未回复', 'afterReplyFollowUpEnabled', 'afterReplyFollowUpDelaySeconds', 'afterReplyFollowUpMessage', '请输入 AI Agents 回复后客户未回复时的跟进语')}
    </div></section>
    <section className="detail-section reception-card"><div className="detail-section-head"><h2>结束语</h2><Switch checked={reception.closingMessageEnabled} onChange={(checked) => save({ closingMessageEnabled: checked })} aria-label="结束语开关" /></div>{reception.closingMessageEnabled && <div className="detail-section-body"><Input.TextArea value={reception.closingMessage} maxLength={500} showCount autoSize={{ minRows: 3, maxRows: 8 }} placeholder="请输入会话关闭前发送的结束语" onChange={(closingMessage: string) => save({ closingMessage })} /></div>}</section>
  </div>;
}

function FlowSection({ agent }: { agent: Agent }) {
  const { dispatch } = useAppStore(); const toast = Message; const [selectedId, setSelectedId] = useState(agent.draft.flows[0]?.id); const [draft, setDraft] = useState<Flow | undefined>(agent.draft.flows[0]);
  const selectFlow = (flow: Flow) => { setSelectedId(flow.id); setDraft(flow); };
  const createFlow = () => { const created: Flow = { id: id('flow'), name: '新流程', trigger: '', content: '<p></p>', contentHtml: '<p></p>', updatedAt: now() }; setDraft(created); setSelectedId(created.id); };
  const save = () => { if (!draft?.name || !draft.trigger || !draft.contentHtml || draft.contentHtml === '<p></p>') { toast.error('请填写流程名称、触发器和内容'); return; } const exists = agent.draft.flows.some((item) => item.id === draft.id); const flows = exists ? updateFlow(agent.draft, draft).flows : [...agent.draft.flows, draft]; dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, flows } }); toast.success('流程已保存'); };
  const copy = (flow: Flow) => { const copied = { ...flow, id: id('flow'), name: `${flow.name} 副本`, updatedAt: now() }; dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, flows: [...agent.draft.flows, copied] } }); setDraft(copied); setSelectedId(copied.id); toast.success('流程已复制'); };
  const remove = (flow: Flow) => { const flows = agent.draft.flows.filter((item) => item.id !== flow.id); dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, flows } }); setDraft(flows[0]); setSelectedId(flows[0]?.id); toast.success('流程已删除'); };
  return <div className="detail-layout"><Card className="section-card flow-list" title="流程" extra={<Button type="text" icon={<IconPlus />} onClick={createFlow}>新建</Button>}>{agent.draft.flows.length ? agent.draft.flows.map((flow) => <div className={`flow-item ${flow.id === selectedId ? 'active' : ''}`} key={flow.id} onClick={() => selectFlow(flow)}><span className="flow-item-name">{flow.name}</span><Space size={0}><Button type="text" size="small" icon={<IconCopy />} onClick={(event: MouseEvent<HTMLElement>) => { event.stopPropagation(); copy(flow); }} /><Popconfirm title="确认删除流程？" onConfirm={(event: MouseEvent<HTMLElement>) => { event?.stopPropagation(); remove(flow); }}><Button type="text" danger size="small" icon={<IconDelete />} onClick={(event: MouseEvent<HTMLElement>) => event.stopPropagation()} /></Popconfirm></Space></div>) : <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="暂无流程" />}<div style={{ padding: 16 }}><Button block type="dashed" icon={<IconPlus />} onClick={createFlow}>新建流程</Button></div></Card><Card className="section-card" title={draft ? '流程编辑' : '选择一个流程'} extra={draft && <Button type="primary" icon={<IconSave />} onClick={save}>保存流程</Button>}>{draft ? <FlowEditor draft={draft} setDraft={setDraft} /> : <Empty description="从左侧新建或选择流程" />}</Card></div>;
}

function FlowEditor({ draft, setDraft }: { draft: Flow; setDraft: (flow: Flow) => void }) {
  return <div><Form layout="vertical"><Form.Item label="流程名称" required><Input maxLength={50} value={draft.name} onChange={(value: string) => setDraft({ ...draft, name: value })} /></Form.Item><Form.Item label="触发器" required><Input.TextArea maxLength={500} showCount rows={3} value={draft.trigger} onChange={(value: string) => setDraft({ ...draft, trigger: value })} placeholder="描述什么情况下智能体应该使用该流程" /></Form.Item><Form.Item label="内容" required><RichTextEditor value={draft.contentHtml} onChange={(html, text) => setDraft({ ...draft, content: text, contentHtml: html })} /><div className="muted" style={{ marginTop: 8 }}>支持标题、加粗、有序列表、无序列表、引用、分割线、撤销和重做。内容最多 10000 字。</div></Form.Item></Form></div>;
}

function SkillSection({ agent }: { agent: Agent }) {
  const { state, dispatch } = useAppStore(); const toast = Message; const [open, setOpen] = useState(false); const enabled = state.skills.filter((skill) => skill.enabled); const attached = state.skills.filter((skill) => agent.draft.skillIds.includes(skill.id)); const [selected, setSelected] = useState(agent.draft.skillIds);
  const save = () => { dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, skillIds: selected } }); setOpen(false); toast.success('技能绑定已保存'); };
  return <div><div className="filter-bar"><span className="muted">仅可添加已启用技能，当前已绑定 {attached.length} 个</span><Button type="primary" icon={<IconPlus />} onClick={() => { setSelected(agent.draft.skillIds); setOpen(true); }}>添加技能</Button></div>{attached.length ? <Table rowKey="id" dataSource={attached} pagination={false} columns={[{ title: '技能名称', dataIndex: 'name', render: (value: string) => <Space><IconThunderbolt style={{ color: 'var(--color-primary)' }} />{value}</Space> }, { title: '描述', dataIndex: 'description' }, { title: '最近更新', dataIndex: 'updatedAt', render: formatDate }, { title: '操作', render: (_: unknown, item: Skill) => <Popconfirm title="确认从智能体分离技能？" onConfirm={() => { dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, skillIds: agent.draft.skillIds.filter((id) => id !== item.id) } }); toast.success('技能已分离'); }}><Button type="text" danger>分离</Button></Popconfirm> }]} /> : <Empty description="当前智能体尚未绑定技能"><Button type="primary" onClick={() => setOpen(true)}>添加技能</Button></Empty>}<Modal open={open} title="添加技能" onCancel={() => setOpen(false)} onOk={save} okText="保存"><Checkbox.Group value={selected} onChange={(values) => setSelected(values as string[])} style={{ display: 'grid', gap: 12 }}>{enabled.map((skill) => <Checkbox key={skill.id} value={skill.id}><b>{skill.name}</b><span className="muted">　{skill.description}</span></Checkbox>)}</Checkbox.Group></Modal></div>;
}

function KnowledgeSection({ agent }: { agent: Agent }) {
  const { state, dispatch } = useAppStore(); const toast = Message; const [open, setOpen] = useState(false); const [selected, setSelected] = useState(agent.draft.knowledgeIds); const attached = state.documents.filter((doc) => agent.draft.knowledgeIds.includes(doc.id)); const available = state.documents.filter((doc) => doc.status === 'success');
  const save = () => { dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, knowledgeIds: selected } }); setOpen(false); toast.success('知识库绑定已保存'); };
  return <div><div className="filter-bar"><span className="muted">知识文档更新后会即时影响已绑定智能体</span><Button type="primary" icon={<IconPlus />} onClick={() => { setSelected(agent.draft.knowledgeIds); setOpen(true); }}>添加知识库</Button></div>{attached.length ? <Table rowKey="id" dataSource={attached} pagination={false} columns={[{ title: '类型', dataIndex: 'type', width: 100 }, { title: '名称', dataIndex: 'name' }, { title: '来源信息', dataIndex: 'source', render: (value: string, item: KnowledgeDocument) => item.size ? `${(item.size / 1024).toFixed(1)} KB` : value }, { title: '最近更新', dataIndex: 'updatedAt', render: formatDate }, { title: '操作', render: (_: unknown, item: KnowledgeDocument) => <Space><Button type="text" onClick={() => toast.info(item.content)}>查看详情</Button><Popconfirm title="确认从智能体分离知识？" description="分离后当前智能体将无法继续检索该内容。" onConfirm={() => { dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, knowledgeIds: agent.draft.knowledgeIds.filter((id) => id !== item.id) } }); toast.success('知识已分离'); }}><Button type="text" danger>分离</Button></Popconfirm></Space> }]} /> : <Empty description="当前智能体尚未绑定知识库"><Button type="primary" onClick={() => setOpen(true)}>添加知识库</Button></Empty>}<Modal open={open} title="添加知识库" onCancel={() => setOpen(false)} onOk={save} okText="保存"><Checkbox.Group value={selected} onChange={(values) => setSelected(values as string[])} style={{ display: 'grid', gap: 12 }}>{available.map((doc) => <Checkbox key={doc.id} value={doc.id}><b>{doc.name}</b><span className="muted">　{doc.type} · {doc.source}</span></Checkbox>)}</Checkbox.Group></Modal></div>;
}

function GuardsSection({ agent }: { agent: Agent }) {
  const { dispatch } = useAppStore(); const toast = Message; const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Guard>(); const [form] = Form.useForm();
  const save = async () => { const values = await form.validateFields(); const item: Guard = { id: editing?.id || id('guard'), name: values.name, prompt: values.prompt, action: values.action, fixedReply: values.fixedReply || '', enabled: values.enabled ?? true, updatedAt: now() }; const guards = editing ? agent.draft.guards.map((guard) => guard.id === editing.id ? item : guard) : [...agent.draft.guards, item]; dispatch({ type: 'agent.config', id: agent.id, config: updateGuards(agent.draft, guards) }); toast.success(editing ? '防护措施已更新' : '防护措施已创建'); setOpen(false); };
  return <div><div className="filter-bar"><span className="muted">防护措施优先于流程、知识库和技能</span><Button type="primary" icon={<IconPlus />} onClick={() => { setEditing(undefined); form.resetFields(); form.setFieldsValue({ action: 'fixed', enabled: true }); setOpen(true); }}>新建防护措施</Button></div><Table rowKey="id" dataSource={agent.draft.guards} pagination={false} columns={[{ title: '名称', dataIndex: 'name' }, { title: '违规时操作', dataIndex: 'action', render: (value: Guard['action']) => value === 'end' ? '结束会话' : '回复固定话术' }, { title: '状态', dataIndex: 'enabled', render: (value: boolean) => <Tag color={value ? 'success' : 'default'}>{value ? '启用' : '关闭'}</Tag> }, { title: '最近更新', dataIndex: 'updatedAt', render: formatDate }, { title: '操作', render: (_: unknown, item: Guard) => <Space><Button type="text" icon={<IconEdit />} onClick={() => { setEditing(item); form.setFieldsValue(item); setOpen(true); }}>编辑</Button><Button type="text" onClick={() => { const copied = { ...item, id: id('guard'), name: `${item.name} 副本` }; dispatch({ type: 'agent.config', id: agent.id, config: updateGuards(agent.draft, [...agent.draft.guards, copied]) }); toast.success('防护措施已复制'); }}>复制</Button><Popconfirm title="删除防护措施后规则将不再生效。确认删除？" onConfirm={() => { dispatch({ type: 'agent.config', id: agent.id, config: updateGuards(agent.draft, agent.draft.guards.filter((guard) => guard.id !== item.id)) }); toast.success('防护措施已删除'); }}><Button type="text" danger>删除</Button></Popconfirm></Space> }]} /><Modal open={open} title={editing ? '编辑防护措施' : '新建防护措施'} onCancel={() => setOpen(false)} onOk={save} okText="保存"><Form form={form} layout="vertical"><Form.Item name="name" label="防护措施名称" rules={[{ required: true, message: '请输入名称' }]}><Input /></Form.Item><Form.Item name="prompt" label="提示词" rules={[{ required: true, message: '请输入提示词' }]}><Input.TextArea rows={4} /></Form.Item><Form.Item name="action" label="违规时操作" rules={[{ required: true }]}><Select options={[{ label: '结束会话', value: 'end' }, { label: '回复固定话术', value: 'fixed' }]} /></Form.Item><Form.Item shouldUpdate={(prev: { action?: string }, current: { action?: string }) => prev.action !== current.action}>{({ getFieldValue }: { getFieldValue: (name: string) => unknown }) => getFieldValue('action') === 'fixed' ? <Form.Item name="fixedReply" label="固定回复话术" rules={[{ required: true, message: '请输入固定回复话术' }]}><Input.TextArea rows={3} /></Form.Item> : null}</Form.Item><Form.Item name="enabled" label="启用状态" valuePropName="checked"><Switch /></Form.Item></Form></Modal></div>;
}

function VariablesSection({ agent }: { agent: Agent }) {
  const { dispatch } = useAppStore(); const toast = Message; const [open, setOpen] = useState(false); const [editing, setEditing] = useState<{ id: string; name: string; value: string; description: string }>(); const [form] = Form.useForm();
  const save = async () => { const values = await form.validateFields(); if (agent.draft.variables.some((item) => item.name === values.name && item.id !== editing?.id)) { toast.error('同一智能体下变量不可重复'); return; } const item = { id: editing?.id || id('var'), name: values.name, value: values.value, description: values.description || '', updatedAt: now() }; const variables = editing ? agent.draft.variables.map((variable) => variable.id === editing.id ? item : variable) : [...agent.draft.variables, item]; dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, variables } }); toast.success('环境变量已保存'); setOpen(false); };
  return <div><div className="filter-bar"><span className="muted">变量可在系统提示词、流程内容和技能调用说明中使用，例如 {'{{API_KEY}}'}</span><Button type="primary" icon={<IconPlus />} onClick={() => { setEditing(undefined); form.resetFields(); setOpen(true); }}>新建变量</Button></div><Table rowKey="id" dataSource={agent.draft.variables} pagination={false} columns={[{ title: '变量', dataIndex: 'name', render: (value: string) => <span className="mono">{`{{${value}}}`}</span> }, { title: '值', dataIndex: 'value', render: (value: string) => <span className="mono">{value}</span> }, { title: '描述', dataIndex: 'description' }, { title: '最近更新', dataIndex: 'updatedAt', render: formatDate }, { title: '操作', render: (_: unknown, item: EnvironmentVariable) => <Space><Button type="text" onClick={() => { setEditing(item); form.setFieldsValue(item); setOpen(true); }}>编辑</Button><Popconfirm title="确认删除环境变量？" onConfirm={() => { dispatch({ type: 'agent.config', id: agent.id, config: { ...agent.draft, variables: agent.draft.variables.filter((variable) => variable.id !== item.id) } }); toast.success('环境变量已删除'); }}><Button type="text" danger>删除</Button></Popconfirm></Space> }]} /><Modal open={open} title={editing ? '编辑环境变量' : '新建环境变量'} onCancel={() => setOpen(false)} onOk={save} okText="保存"><Form form={form} layout="vertical"><Form.Item name="name" label="变量" rules={[{ required: true, message: '请输入变量名称' }, { pattern: /^[A-Z_][A-Z0-9_]*$/, message: '仅支持英文大写字母、数字和下划线，且不能以数字开头' }]}><Input placeholder="API_KEY" /></Form.Item><Form.Item name="value" label="值" rules={[{ required: true, message: '请输入变量值' }]}><Input.Password /></Form.Item><Form.Item name="description" label="描述"><Input /></Form.Item></Form></Modal></div>;
}

function TestDrawer({ agent, open, onClose }: { agent: Agent; open: boolean; onClose: () => void }) {
  const { state } = useAppStore(); const [input, setInput] = useState(''); const [messages, setMessages] = useState<{ role: 'user' | 'agent' | 'system'; content: string }[]>([]); const [hits, setHits] = useState<string[]>([]); const toast = Message;
  const run = (message = input) => { if (!message.trim()) { toast.warning('请输入测试消息'); return; } const lower = message.toLowerCase(); const next: string[] = []; let reply = '我会根据当前草稿配置继续为你处理这个问题。'; if (lower.includes('订单') || lower.includes('物流')) { next.push(`流程：${agent.draft.flows[0]?.name || '未配置流程'}`); if (agent.draft.knowledgeIds.length) next.push(`知识：${state.documents.find((doc) => agent.draft.knowledgeIds.includes(doc.id))?.name || '知识文档'}`); reply = '请提供订单号，我来帮你查询物流进度。'; } if (lower.includes('token') || lower.includes('密码') || lower.includes('密钥')) { next.push(`防护措施：${agent.draft.guards[0]?.name || '敏感信息保护'}`); reply = agent.draft.guards[0]?.fixedReply || '抱歉，我无法协助处理该类内容。'; } if (lower.includes('人工')) { next.push('转人工：已配置 LiveChat 转人工 Group'); reply = '好的，我正在为你转接人工客服。'; } if (lower.includes('异常')) { next.push('模型异常：使用模型异常话术'); reply = agent.draft.errorMessage; } if (lower.includes('技能')) { next.push(`技能：${state.skills.find((skill) => agent.draft.skillIds.includes(skill.id))?.name || '未配置技能'}`); reply = '已模拟调用技能并返回结果。'; } setMessages((prev) => [...prev, { role: 'user', content: message }, ...next.map((item) => ({ role: 'system' as const, content: item })), { role: 'agent', content: reply }]); setHits(next); setInput(''); };
  const presets = ['查询订单物流', '我想找人工客服', '请提供 Token', '触发模型异常', '模拟技能调用'];
  return <Drawer open={open} onClose={onClose} size="large" title="测试面板" extra={<Tag color="arcoblue">使用草稿配置</Tag>}><div className="test-panel"><div><div className="test-messages">{messages.length ? messages.map((item, index) => item.role === 'system' ? <div className="system-event" key={index}>· {item.content} ·</div> : <div className={`chat-message ${item.role}`} key={index}><Avatar size={28}>{item.role === 'user' ? '我' : '灵'}</Avatar><div className="chat-bubble">{item.content}</div></div>) : <Empty description="发送一条消息，查看命中结果" />}</div><Space style={{ width: '100%', marginTop: 12 }}><Input value={input} onChange={(value) => setInput(value)} onPressEnter={() => run()} placeholder="例如：我的订单到哪里了？" /><Button type="primary" icon={<IconSend />} onClick={() => run()}>发送</Button></Space><Space wrap style={{ marginTop: 12 }}>{presets.map((preset) => <Button key={preset} size="small" onClick={() => run(preset)}>{preset}</Button>)}</Space></div><div><Card size="small" title="命中详情">{hits.length ? <div className="hit-list">{hits.map((hit) => <div className="hit-item" key={hit}>{hit}</div>)}</div> : <span className="muted">运行后展示命中流程、知识、技能、防护、转人工和异常。</span>}</Card></div></div></Drawer>;
}

void TestDrawer;

type PreviewMessage = { role: 'customer' | 'agent'; content: string; type: 'text' | 'image'; imageUrl?: string; sentAt: string };

const formatPreviewTime = (value: string) => new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value));

function AgentPreviewPanel({ agent }: { agent: Agent }) {
  const toast = Message;
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<PreviewMessage[]>([]);
  const imageInputId = `preview-image-upload-${agent.id}`;
  const replyFor = (message: string) => message.includes('订单') || message.includes('物流') ? '请提供订单号，我来帮你查询物流进度。' : message.includes('人工') ? '好的，我正在为你转接人工客服。' : '我会根据当前草稿配置继续为你处理这个问题。';
  const appendExchange = (customer: Omit<PreviewMessage, 'role' | 'sentAt'>, agentReply: string) => setMessages((prev) => [...prev, { ...customer, role: 'customer' as const, sentAt: new Date().toISOString() }, { role: 'agent' as const, content: agentReply, type: 'text' as const, sentAt: new Date().toISOString() }]);
  const run = () => {
    const message = input.trim();
    if (!message) return;
    appendExchange({ content: message, type: 'text' }, replyFor(message));
    setInput('');
  };
  const sendImage = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.currentTarget.value = '';
    if (!file) return;
    if (!file.type.startsWith('image/')) { toast.error('仅支持上传图片文件'); return; }
    const reader = new FileReader();
    reader.onload = () => appendExchange({ content: '', type: 'image', imageUrl: String(reader.result) }, '已收到你发送的图片。');
    reader.readAsDataURL(file);
  };
  const clearAll = () => { if (!messages.length) { toast.info('当前没有可清除的消息'); return; } setMessages([]); setInput(''); toast.success('已清除全部消息'); };
  return <aside className="agent-preview-panel"><div className="preview-panel-head"><h2>预览与测试</h2><Button type="text" shape="circle" icon={<BroomIcon />} aria-label="清除全部消息" onClick={clearAll} /></div><div className="preview-panel-messages preview-chat">{messages.length ? messages.map((item, index) => <div className={`inbox-message-row is-${item.role}`} key={index}>{item.role === 'agent' && <span className="inbox-agent-avatar"><IconRobot /></span>}<div className="inbox-message-content"><span className="inbox-message-author">{item.role === 'agent' ? agent.name || '未命名 AI Agent' : '我'}</span>{item.type === 'image' ? <figure className="inbox-message-image-card">{item.imageUrl && <img src={item.imageUrl} alt="发送的图片" />}{item.content ? <figcaption>{item.content}</figcaption> : null}</figure> : <div className="inbox-message-bubble">{item.content}</div>}<time>{formatPreviewTime(item.sentAt)}</time></div>{item.role === 'customer' && <span className="inbox-customer-avatar is-message tone-1">我</span>}</div>) : <div className="preview-panel-empty"><img src={agent.avatar || AVATAR_PLACEHOLDER} alt="" /><strong>{agent.name || '未命名 AI Agent'}</strong><span>输入问题开始测试</span></div>}</div><div className="preview-panel-input"><Button type="text" icon={<IconImage />} aria-label="上传图片" onClick={() => document.getElementById(imageInputId)?.click()} /><input id={imageInputId} type="file" accept="image/*" hidden onChange={sendImage} /><Input value={input} onChange={setInput} onPressEnter={run} placeholder="输入消息……" /><Button type="primary" icon={<IconSend />} aria-label="发送" onClick={run} /></div></aside>;
}

function MonitorSection({ agent }: { agent: Agent }) {
  const { state } = useAppStore(); const [channel, setChannel] = useState('全部渠道'); const [status, setStatus] = useState('全部状态'); const [hit, setHit] = useState('全部命中'); const [selected, setSelected] = useState<typeof state.sessions[number]>(); const channels = state.channels.filter((item) => item.agentId === agent.id); const sessions = state.sessions.filter((item) => item.agentId === agent.id && (channel === '全部渠道' || item.channel === channel) && (status === '全部状态' || item.status === status) && (hit === '全部命中' || item.hits.some((value) => value.includes(hit)))); const metrics = [{ label: '会话数', value: sessions.length }, { label: '消息数', value: sessions.reduce((sum, item) => sum + item.messageCount, 0) }, { label: '转人工数', value: sessions.filter((item) => item.status === 'human').length }, { label: '异常数', value: sessions.filter((item) => item.status === 'error').length }, { label: '平均响应', value: '1.8s' }];
  return <div><div className="filter-bar"><Space wrap><Radio.Group type="button" value={channel} onChange={setChannel} options={['全部渠道', ...channels.map((item) => item.name)]} /><Select value={status} onChange={setStatus} options={[['全部状态', '全部状态'], ['active', '进行中'], ['ended', '已结束'], ['human', '已转人工'], ['error', '异常']].map(([value, label]) => ({ label, value }))} style={{ width: 130 }} /><Select value={hit} onChange={setHit} options={['全部命中', '流程', '知识', '技能', '防护措施', '转人工', '模型异常'].map((value) => ({ label: value, value }))} style={{ width: 130 }} /></Space><DatePicker.RangePicker /></div><div className="metric-grid">{metrics.map((metric) => <div className="metric-card" key={metric.label}><div className="metric-label">{metric.label}</div><div className="metric-value">{metric.value}</div></div>)}</div><Row gutter={16} style={{ marginTop: 16 }}><Col xs={24} lg={12}><Card className="section-card" title="流程触发 Top"><div className="monitor-list">{agent.draft.flows.map((flow) => <div className="monitor-list-item" key={flow.name}><span>{flow.name}</span><span className="mono">{Math.max(3, sessions.filter((session) => session.hits.some((hitValue) => hitValue.includes(flow.name))).length * 4)} 次</span></div>)}</div></Card></Col><Col xs={24} lg={12}><Card className="section-card" title="异常类型分布"><div className="monitor-list">{['模型异常', '技能调用异常', '渠道发送异常', '知识检索异常'].map((name) => <div className="monitor-list-item" key={name}><span>{name}</span><span className="mono">{name === '模型异常' ? sessions.filter((session) => session.status === 'error').length : 0} 次</span></div>)}</div></Card></Col></Row><Card className="section-card" title={`会话记录（${sessions.length}）`} style={{ marginTop: 16 }}><Table rowKey="id" dataSource={sessions} pagination={false} columns={[{ title: '用户 / 会话标题', dataIndex: 'title' }, { title: '渠道', dataIndex: 'channel' }, { title: '开始时间', dataIndex: 'startedAt' }, { title: '消息数', dataIndex: 'messageCount', render: (value: number) => <span className="mono">{value}</span> }, { title: '状态', dataIndex: 'status', render: (value: Session['status']) => <Tag color={value === 'error' ? 'error' : value === 'human' ? 'warning' : value === 'ended' ? 'success' : 'processing'}>{value === 'active' ? '进行中' : value === 'ended' ? '已结束' : value === 'human' ? '已转人工' : '异常'}</Tag> }, { title: '操作', render: (_: unknown, item: Session) => <Button type="text" icon={<IconEye />} onClick={() => setSelected(item)}>查看详情</Button> }]} /></Card><Drawer open={Boolean(selected)} onClose={() => setSelected(undefined)} title="会话详情" size="large">{selected && <><Descriptions column={1} bordered size="small" items={[{ key: 'title', label: '会话标题', children: selected.title }, { key: 'channel', label: '渠道', children: selected.channel }, { key: 'time', label: '开始时间', children: selected.startedAt }, { key: 'status', label: '会话状态', children: selected.status }]} /><Divider /><div className="session-messages">{selected.messages.map((item, index) => <div className="session-message" key={index}><Tag>{item.role === 'user' ? '用户' : item.role === 'agent' ? '智能体' : '系统事件'}</Tag>{item.content}</div>)}</div><Divider /><h3>命中详情</h3><div className="hit-list">{selected.hits.map((item) => <div className="hit-item" key={item}>{item}</div>)}</div></>}</Drawer></div>;
}

function AgentDetailPage() {
  const { id: agentId, section = 'agent' } = useParams(); const navigate = useNavigate(); const { state, dispatch } = useAppStore(); const toast = Message; const [previewWidth, setPreviewWidth] = useState(360); const resizing = useRef(false); const agent = state.agents.find((item) => item.id === agentId);
  useEffect(() => { const move = (event: globalThis.MouseEvent) => { if (!resizing.current) return; const next = window.innerWidth - event.clientX; setPreviewWidth(Math.min(640, Math.max(320, next))); }; const up = () => { resizing.current = false; document.body.style.cursor = ''; document.body.style.userSelect = ''; }; window.addEventListener('mousemove', move); window.addEventListener('mouseup', up); return () => { window.removeEventListener('mousemove', move); window.removeEventListener('mouseup', up); }; }, []);
  useEffect(() => { if (agent && !AGENT_DETAIL_SECTIONS.some((item) => item.key === section)) navigate(`/agents/${agent.id}/agent`, { replace: true }); }, [agent, navigate, section]);
  if (!agent) return <div className="page-content"><Empty description="AI Agent 不存在"><Button onClick={() => navigate('/agents')}>返回 AI Agents 列表</Button></Empty></div>;
  const publish = () => { if (!agent.name.trim()) { toast.error('请输入 AI Agent 名称'); return; } dispatch({ type: 'agent.publish', id: agent.id }); toast.success('AI Agent 已发布'); };
  const activeSection = AGENT_DETAIL_SECTIONS.some((item) => item.key === section) ? section : 'agent';
  const navGroups = [{ title: '配置', items: AGENT_DETAIL_SECTIONS }];
  const sectionContent = activeSection === 'knowledge' ? <KnowledgeSectionV2 agent={agent} /> : activeSection === 'workflow' ? <AgentWorkflowSection key={agent.id} agent={agent} /> : activeSection === 'reception' ? <ReceptionSection agent={agent} /> : <AgentBasics agent={agent} />;
  return <div className="detail-page"><PageHeader title={<div className="detail-title"><Button type="text" shape="circle" icon={<IconArrowLeft />} aria-label="返回 AI Agents 列表" onClick={() => navigate('/agents')} /><span className="detail-agent-title">{agent.name || '未命名'}</span></div>} status={agent.status} extra={<span className="save-time">最近保存：{formatDate(agent.updatedAt)}</span>} actions={<div className="agent-detail-actions"><span className="accept-chat-control">接受聊天<Switch checked={agent.acceptingChats} onChange={(checked) => { if (checked && agent.status !== 'published') { toast.warning('请先发布 AI Agent 后再开启接受聊天'); return; } dispatch({ type: 'agent.update', id: agent.id, patch: { acceptingChats: Boolean(checked) } }); }} /></span><Button type="primary" icon={<IconSend />} onClick={publish}>发布</Button></div>} /><div className="detail-workspace"><nav className="detail-nav">{navGroups.map((group) => <div className="detail-nav-group" key={group.title}><div className="detail-nav-title">{group.title}</div>{group.items.map((item) => <button className={`detail-nav-item ${activeSection === item.key ? 'active' : ''}`} key={item.key} onClick={() => navigate(`/agents/${agent.id}/${item.key}`)}>{item.label}</button>)}</div>)}</nav><main className="detail-config-area"><div className="detail-section-page">{!['knowledge', 'workflow'].includes(activeSection) && <h1 className="detail-page-section-title">{AGENT_DETAIL_SECTION_TITLES[activeSection]}</h1>}{sectionContent}</div></main><div className="detail-resizer" role="separator" aria-label="调整预览与测试面板宽度" onMouseDown={() => { resizing.current = true; document.body.style.cursor = 'col-resize'; document.body.style.userSelect = 'none'; }} /><div className="detail-preview-wrap" style={{ width: previewWidth }}><AgentPreviewPanel agent={agent} /></div></div></div>;
}

function KnowledgePage() {
  const { state, dispatch } = useAppStore(); const toast = Message; const [urlOpen, setUrlOpen] = useState(false); const [detail, setDetail] = useState<KnowledgeDocument>(); const [editing, setEditing] = useState<KnowledgeDocument>(); const [form] = Form.useForm(); const [query, setQuery] = useState('');
  const docs = state.documents.filter((doc) => `${doc.name}${doc.source}`.toLowerCase().includes(query.toLowerCase()));
  const addUrl = async () => { const values = await form.validateFields(); if (!values.url.startsWith('https://')) { toast.error('请输入以 https:// 开头的 URL，例如：https://example.com。'); return; } const document: KnowledgeDocument = { id: id('doc'), type: 'URL', name: values.name || values.url, source: values.url, creator: '当前用户', status: 'adding', content: '正在模拟抓取并解析网页内容…', updatedAt: now() }; dispatch({ type: 'document.add', document }); setUrlOpen(false); form.resetFields(); toast.success('URL 已加入解析队列'); window.setTimeout(() => { dispatch({ type: 'document.update', id: document.id, patch: { status: 'success', content: `已解析页面 ${document.name}。这是本地 mock 内容，用于测试知识库绑定和检索流程。` } }); }, 700); };
  const addFiles = async (files: FileList | null) => { if (!files) return; for (const file of Array.from(files)) { const ext = file.name.split('.').pop()?.toUpperCase() || ''; if (!['PDF', 'TXT', 'MD', 'DOC', 'DOCX', 'XLSX', 'CSV'].includes(ext)) { toast.error(`${file.name} 格式不支持`); continue; } if (file.size > 100 * 1024 * 1024) { toast.error(`${file.name} 超过 100M 限制`); continue; } const document: KnowledgeDocument = { id: id('doc'), type: ext, name: file.name, source: file.name, size: file.size, creator: '当前用户', status: 'adding', content: '正在模拟上传和解析文件…', updatedAt: now() }; dispatch({ type: 'document.add', document }); window.setTimeout(() => { dispatch({ type: 'document.update', id: document.id, patch: { status: 'success', content: `已解析文件 ${file.name}。该内容来自本地 mock 解析结果。` } }); }, 700); } toast.success('文件已加入上传队列'); };
  const saveEdit = async () => { const values = await form.validateFields(); if (editing) { dispatch({ type: 'document.update', id: editing.id, patch: { name: values.name, source: editing.type === 'URL' ? values.url : editing.source } }); toast.success('知识文档已更新'); } setEditing(undefined); };
  return <div className="page-content"><PageHeader title="知识库" breadcrumb={['客户支持智能体']} actions={<Space><Button icon={<IconLink />} onClick={() => { form.resetFields(); setUrlOpen(true); }}>添加 URL</Button><Button type="primary" icon={<IconUpload />} onClick={() => document.getElementById('knowledge-upload')?.click()}>上传文件</Button><input id="knowledge-upload" type="file" multiple hidden accept=".pdf,.txt,.md,.doc,.docx,.xlsx,.csv" onChange={(event: ChangeEvent<HTMLInputElement>) => { void addFiles(event.target.files); event.currentTarget.value = ''; }} /></Space>} /><div className="filter-bar"><Input.Search value={query} onChange={setQuery} allowClear placeholder="搜索知识文档" style={{ width: 300 }} /><span className="muted">一个 URL 或一个文件生成一条知识文档</span></div><Table rowKey="id" dataSource={docs} columns={[{ title: '类型', dataIndex: 'type', width: 100 }, { title: '名称', dataIndex: 'name' }, { title: '来源信息', dataIndex: 'source', render: (value: string, item: KnowledgeDocument) => item.size ? `${(item.size / 1024).toFixed(1)} KB` : value }, { title: '创建者', dataIndex: 'creator' }, { title: '状态', dataIndex: 'status', render: (value: KnowledgeDocument['status']) => <Tag color={value === 'success' ? 'success' : value === 'failed' ? 'error' : 'processing'}>{value === 'success' ? '已添加成功' : value === 'failed' ? '添加失败' : '添加中'}</Tag> }, { title: '最近更新', dataIndex: 'updatedAt', render: formatDate }, { title: '操作', render: (_: unknown, item: KnowledgeDocument) => <Space><Button type="text" icon={<IconEye />} onClick={() => setDetail(item)}>查看详情</Button><Button type="text" icon={<IconEdit />} onClick={() => { setEditing(item); form.setFieldsValue({ name: item.name, url: item.source }); }}>编辑</Button><Popconfirm title="删除知识文档后相关智能体将自动解除绑定。确认删除？" onConfirm={() => { dispatch({ type: 'document.delete', id: item.id }); toast.success('知识文档已删除'); }}><Button type="text" danger>删除</Button></Popconfirm></Space> }]} pagination={{ pageSize: 8 }} /><Drawer open={Boolean(detail)} onClose={() => setDetail(undefined)} title="知识文档详情" size="large">{detail && <><Descriptions bordered column={1} size="small" items={[{ key: 'type', label: '类型', children: detail.type }, { key: 'name', label: '名称', children: detail.name }, { key: 'source', label: '来源', children: detail.source }, { key: 'updated', label: '更新时间', children: formatDate(detail.updatedAt) }]} /><Divider /><h3>解析内容</h3><div style={{ whiteSpace: 'pre-wrap' }}>{detail.content}</div></>}</Drawer><Modal open={urlOpen} title="添加 URL" onCancel={() => setUrlOpen(false)} onOk={addUrl} okText="添加"><Form form={form} layout="vertical"><Form.Item name="url" label="URL" rules={[{ required: true, message: '请输入 URL' }]}><Input placeholder="https://example.com" /></Form.Item><Form.Item name="name" label="名称"><Input placeholder="可选" /></Form.Item></Form></Modal><Modal open={Boolean(editing)} title="编辑知识文档" onCancel={() => setEditing(undefined)} onOk={saveEdit} okText="保存"><Form form={form} layout="vertical"><Form.Item name="name" label="名称" rules={[{ required: true }]}><Input /></Form.Item>{editing?.type === 'URL' && <Form.Item name="url" label="URL" rules={[{ required: true }]}><Input /></Form.Item>}</Form></Modal></div>;
}

function SkillsPage() {
  const { state, dispatch } = useAppStore(); const toast = Message; const [query, setQuery] = useState(''); const skills = state.skills.filter((skill) => `${skill.name}${skill.description}`.toLowerCase().includes(query.toLowerCase()));
  const upload = (file: File) => { const ext = file.name.split('.').pop()?.toLowerCase(); if (!['zip', 'md'].includes(ext || '')) { toast.error('仅支持 .zip 或 .md 技能文件'); return; } const skill: Skill = { id: id('skill'), name: file.name.replace(/\.(zip|md)$/i, ''), description: `从 ${file.name} 导入的技能能力包`, enabled: true, updatedAt: now() }; dispatch({ type: 'skill.add', skill }); toast.success('技能上传成功'); };
  return <div className="page-content"><PageHeader title="技能" breadcrumb={['客户支持智能体']} actions={<Button type="primary" icon={<IconUpload />} onClick={() => document.getElementById('skill-upload')?.click()}>上传技能</Button>} /><input id="skill-upload" type="file" hidden accept=".zip,.md" onChange={(event) => { const file = event.target.files?.[0]; if (file) upload(file); event.currentTarget.value = ''; }} /><div className="filter-bar"><Input.Search value={query} onChange={setQuery} allowClear placeholder="搜索技能" style={{ width: 300 }} /><span className="muted">关闭或删除技能会同步解除智能体绑定关系</span></div>{skills.length ? <div className="resource-grid">{skills.map((skill) => <Card key={skill.id} className="section-card resource-card"><div className="resource-card-title"><div className="resource-icon"><IconThunderbolt /></div><div style={{ minWidth: 0 }}><div className="agent-name">{skill.name}</div><div className="muted">更新于 {formatDate(skill.updatedAt)}</div></div></div><div className="resource-description">{skill.description}</div><Divider /><Space style={{ width: '100%', justifyContent: 'space-between' }}><Switch checked={skill.enabled} onChange={(checked) => { if (!checked) Modal.confirm({ title: '确认关闭技能？', content: '关闭技能后，已添加该技能的智能体将无法继续调用，相关绑定关系将同步移除。', onOk: () => { dispatch({ type: 'skill.toggle', id: skill.id, enabled: false }); toast.success('技能已关闭'); } }); else { dispatch({ type: 'skill.toggle', id: skill.id, enabled: true }); toast.success('技能已启用'); } }} checkedChildren="启用" unCheckedChildren="关闭" /><Popconfirm title="确认删除技能？" description="删除后相关智能体绑定关系将同步移除。" onConfirm={() => { dispatch({ type: 'skill.delete', id: skill.id }); toast.success('技能已删除'); }}><Button status="danger" type="text" icon={<IconDelete />}>删除</Button></Popconfirm></Space></Card>)}</div> : <Empty description="暂无技能" />}</div>;
}

function ChannelModal({ open, onClose, channel }: { open: boolean; onClose: () => void; channel?: Channel }) {
  const { state, dispatch } = useAppStore(); const toast = Message; const [form] = Form.useForm(); const published = state.agents.filter((agent) => agent.status === 'published');
  const save = async () => { const values = await form.validateFields(); const item: Channel = { id: channel?.id || id('channel'), name: values.name, agentId: values.agentId, enabled: values.enabled ?? true, accountId: values.accountId, accessToken: values.accessToken, receiveGroups: values.receiveGroups, humanGroups: values.humanGroups || [], opening: values.opening || '', hotQuestions: values.hotQuestions ? values.hotQuestions.split('\n').filter(Boolean) : [], ending: values.ending || '', humanEnabled: values.humanEnabled ?? false, humanFallback: values.humanFallback || '', updatedAt: now() }; dispatch({ type: 'channel.save', channel: item }); toast.success(channel ? '渠道配置已保存' : '渠道已创建'); onClose(); };
  return <Modal open={open} title={channel ? '配置 LiveChat 渠道' : '新建 LiveChat 渠道'} width={720} onCancel={onClose} onOk={save} okText="保存"><Form form={form} layout="vertical" initialValues={channel || { enabled: true, humanEnabled: true, opening: '你好，我是灵犀智能体，很高兴为你提供帮助。', ending: '如果问题已经解决，可以结束本次会话。', humanFallback: '当前人工服务繁忙，请稍后再试。' }}><h3>基础信息</h3><Row gutter={16}><Col span={12}><Form.Item name="name" label="渠道名称" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={12}><Form.Item name="agentId" label="接待 AI Agent" rules={[{ required: true }]}><Select options={published.map((agent) => ({ label: agent.name, value: agent.id }))} /></Form.Item></Col></Row><h3>访问凭证</h3><Row gutter={16}><Col span={12}><Form.Item name="accountId" label="Account ID" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={12}><Form.Item name="accessToken" label="Access Token" rules={[{ required: true }]}><Input.Password /></Form.Item></Col></Row><Button icon={<IconRefresh />} onClick={() => toast.success('凭证校验成功，已拉取 3 个 Group')}>校验并拉取 Group</Button><Divider /><h3>Group 配置</h3><Row gutter={16}><Col span={12}><Form.Item name="receiveGroups" label="接待 Group" rules={[{ required: true }]}><Select mode="multiple" options={['sales', 'support', 'vip'].map((value) => ({ label: value, value }))} /></Form.Item></Col><Col span={12}><Form.Item name="humanGroups" label="转人工 Group"><Select mode="multiple" options={['human-support', 'human-sales'].map((value) => ({ label: value, value }))} /></Form.Item></Col></Row><h3>接待配置</h3><Form.Item name="opening" label="开场白"><Input.TextArea rows={2} /></Form.Item><Form.Item name="hotQuestions" label="热门问题（每行一个）"><Input.TextArea rows={3} /></Form.Item><Form.Item name="ending" label="结束语"><Input.TextArea rows={2} /></Form.Item><h3>转人工</h3><Form.Item name="humanEnabled" label="转人工开关" valuePropName="checked"><Switch /></Form.Item><Form.Item name="humanFallback" label="转人工失败话术"><Input.TextArea rows={2} /></Form.Item><Form.Item name="enabled" label="渠道状态" valuePropName="checked"><Switch /></Form.Item></Form></Modal>;
}

function ChannelsPage() {
  const { state, dispatch } = useAppStore(); const toast = Message; const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Channel>(); const agents = new Map(state.agents.map((agent) => [agent.id, agent.name]));
  return <div className="page-content"><PageHeader title="渠道" breadcrumb={['客户支持智能体']} extra={<Tag color="blue">LiveChat</Tag>} actions={<Button type="primary" icon={<IconPlus />} onClick={() => { setEditing(undefined); setOpen(true); }}>新建渠道</Button>} /><Table rowKey="id" dataSource={state.channels} columns={[{ title: '渠道名称', dataIndex: 'name' }, { title: '接待 AI Agent', dataIndex: 'agentId', render: (value: string) => agents.get(value) || '未绑定' }, { title: '启用状态', dataIndex: 'enabled', render: (value: boolean) => <Tag color={value ? 'success' : 'default'}>{value ? '启用' : '关闭'}</Tag> }, { title: '最近更新', dataIndex: 'updatedAt', render: formatDate }, { title: '操作', render: (_: unknown, item: Channel) => <Space><Button type="text" onClick={() => { setEditing(item); setOpen(true); }}>配置</Button><Popconfirm title="确认删除渠道？" description="删除后该渠道将停止接收消息。" onConfirm={() => { dispatch({ type: 'channel.delete', id: item.id }); toast.success('渠道已删除'); }}><Button type="text" danger>删除</Button></Popconfirm></Space> }]} pagination={false} /><ChannelModal open={open} onClose={() => setOpen(false)} channel={editing} /></div>;
}

